/**
 * engine-server/pipeline/generic-trap-checker.ts — 通用模板退化检测
 *
 * 实现 AR-07 方案三：检查 LLM 输出的角色列表是否全部为通用角色，
 * 如果是且任务约束包含特殊需求，则标记退化并触发重推。
 *
 * 规则：
 * - 角色名匹配通用模式（纯技术缩写 / 无行业限定词）→ 可能退化
 * - 约束包含特殊关键词但无对应角色 → 退化
 * - 无特殊需求 + 通用角色 → 合理，不退化
 *
 * @packageDocumentation
 */
export interface TrapCheckResult {
    passes: boolean;
    reason?: string;
    specialConstraints?: string[];
}
/**
 * 检查 LLM 输出的角色是否全部为通用模板
 */
export declare function checkGenericTrap(roleIds: string[], roleNames: string[], constraints: string[]): TrapCheckResult;
/**
 * 构建重推 prompt
 */
export declare function buildRetryPrompt(specialConstraints: string[], constraints: string[]): string;
